/**
 * Representative photos for the /services page (TRACE-161).
 *
 * The files are reviewed static assets generated by scripts/build-services-page-imagery.mjs.
 * Source, creator, licence and approval status are recorded in
 * docs/imagery/services-page-imagery-manifest.json. They illustrate a kind of home or service;
 * they are never a provider's team, work or results, and never a home Mercurius has served.
 */

export type ResponsiveImage = { src: string; srcSet: string; width: number; height: number };

const file = (key: string, crop: string, width: number) => `/images/services-page/${key}-${crop}-${width}.webp`;

function responsive(key: string, crop: string, widths: readonly number[], ratio: number): ResponsiveImage {
  const largest = widths[widths.length - 1];
  return {
    src: file(key, crop, widths[Math.min(1, widths.length - 1)]),
    srcSet: widths.map((width) => `${file(key, crop, width)} ${width}w`).join(", "),
    width: largest,
    height: Math.round(largest / ratio),
  };
}

export const SERVICES_HERO_IMAGE = {
  alt: "A white single-story home with a dark tile roof, tall palm trees and a neatly kept lawn.",
  /** 3:2, beside the introduction from 1024 px. */
  panel: responsive("hero-home", "panel", [720, 1080, 1440], 3 / 2),
  /** 2:1, below the introduction and actions on smaller screens. */
  banner: responsive("hero-home", "banner", [640, 960, 1280], 2),
} as const;

export const FEATURED_PHOTO_KEYS = ["lawn-mowing", "house-cleaning", "pool-service", "handyman"] as const;
export type FeaturedPhotoKey = (typeof FEATURED_PHOTO_KEYS)[number];

/** 3:2 card crop. Its alt text is empty: the service name below it names the link. */
export function featuredPhoto(key: FeaturedPhotoKey): ResponsiveImage {
  return responsive(key, "card", [320, 480, 640], 3 / 2);
}
